// Pulse — traductions anglaises complémentaires (18/10/2026), ajoutées au dictionnaire par build-en-texts.js.
// exact : texte français entier → anglais ; P(français avec § à la place des valeurs, anglais avec $1, $2…) → modèle.
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const P = (fr, en) => [fr.split('§').map(esc).join('(.+?)'), en];

